from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_validation():
    print("Testing current SSE validation...")

    # Test event with newline
    try:
        ServerSentEvent(event="line1\nline2")
        print("Current: event with newline ALLOWED")
    except ValidationError as e:
        print(f"Current: event with newline RAISED: {e}")

    # Test id with newline
    try:
        ServerSentEvent(id="line1\nline2")
        print("Current: id with newline ALLOWED")
    except ValidationError as e:
        print(f"Current: id with newline RAISED: {e}")

    # Test event with carriage return
    try:
        ServerSentEvent(event="line1\rline2")
        print("Current: event with carriage return ALLOWED")
    except ValidationError as e:
        print(f"Current: event with carriage return RAISED: {e}")

    # Test id with carriage return
    try:
        ServerSentEvent(id="line1\rline2")
        print("Current: id with carriage return ALLOWED")
    except ValidationError as e:
        print(f"Current: id with carriage return RAISED: {e}")

    # Test id with null char (should already be forbidden)
    try:
        ServerSentEvent(id="null\0char")
        print("Current: id with null char ALLOWED")
    except ValidationError as e:
        print(f"Current: id with null char RAISED: {e}")

if __name__ == "__main__":
    test_sse_validation()

