import inspect
from functools import wraps, partial
import asyncio
from asyncio import iscoroutinefunction

def wrap_sync(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)
    return wrapper

def wrap_async(f):
    @wraps(f)
    async def wrapper(*args, **kwargs):
        return await f(*args, **kwargs)
    return wrapper

def sync_func():
    return "sync"

async def async_func():
    return "async"

# Test cases
cases = [
    ("sync", sync_func, False),
    ("async", async_func, True),
    ("wrap_sync_sync", wrap_sync(sync_func), False),
    ("wrap_async_sync", wrap_async(sync_func), True),
    ("wrap_sync_async", wrap_sync(async_func), True),
    ("wrap_async_async", wrap_async(async_func), True),
    ("partial_sync", partial(sync_func), False),
    ("partial_async", partial(async_func), True),
    ("partial_wrap_sync_sync", partial(wrap_sync(sync_func)), False),
    ("partial_wrap_async_sync", partial(wrap_async(sync_func)), True),
    ("partial_wrap_sync_async", partial(wrap_sync(async_func)), True),
    ("partial_wrap_async_async", partial(wrap_async(async_func)), True),
    ("wrap_partial_sync", wrap_sync(partial(sync_func)), False),
    ("wrap_partial_async", wrap_sync(partial(async_func)), True),
]

def check_is_coroutine(call):
    # Simulate Dependant._unwrapped_call
    unwrapped = inspect.unwrap(call)
    if isinstance(unwrapped, partial):
        unwrapped = unwrapped.func

    # Simulate Dependant.is_coroutine_callable
    if inspect.isroutine(unwrapped):
        return iscoroutinefunction(unwrapped)
    if inspect.isclass(unwrapped):
        return False
    dunder_call = getattr(unwrapped, "__call__", None)
    return iscoroutinefunction(dunder_call)

for name, call, expected in cases:
    result = check_is_coroutine(call)
    print(f"{name:25} Expected: {expected}, Got: {result} {'✅' if result == expected else '❌'}")

