import functools
from typing import Any, ForwardRef
from fastapi.dependencies.utils import get_typed_signature
import inspect

# We need to simulate different globals. 
# Since we are in one file, we can't easily have different modules, 
# but we can manually manipulate __globals__ or just use the fact that 
# if we wrap a function from another module, it should fail.

# However, for a simple reproduction script, we can try to see if we can trigger it.

class B:
    pass

def target_func(x: "B"):
    return x

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

wrapped_func = wrapper(target_func)

# In this case, both are in the same module, so they share globals.
# Let's try to make them different.

# We can't easily change __globals__ of a function.
# But we can define the target_func in a way that its globals are different.

# Let's try to use a class method.
class A:
    def method(self, x: "B"):
        return x

def wrapper_method(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

A.method = wrapper_method(A.method)

try:
    sig = get_typed_signature(A().method)
    print("Success")
except Exception as e:
    print(f"Failed: {e}")
    import traceback
    traceback.print_exc()

