import functools
from typing import Any
from fastapi import FastAPI, Depends
from fastapi.dependencies.utils import get_dependant
import pytest

# We need to simulate different modules. 
# We can use a class or just define them in a way that they have different globals.
# But the easiest way is to actually use different modules or mock __globals__.

def test_wrapped_method_type_inference():
    class MyModel:
        pass

    def my_func(a: "MyModel"):
        return a

    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        # Manually change globals to simulate different module
        wrapped.__globals__ = {} 
        return wrapped

    wrapped_func = wrapper(my_func)

    # This should raise NameError because MyModel is not in wrapped_func.__globals__
    # but it is in my_func.__globals__
    try:
        get_dependant(path="/", call=wrapped_func)
    except NameError as e:
        print(f"Caught expected NameError: {e}")
        return

    pytest.fail("Should have raised NameError")

if __name__ == "__main__":
    test_wrapped_method_type_inference()

