import functools
import inspect
from typing import ForwardRef, Any, Dict, List
from fastapi.dependencies.utils import get_typed_signature

class B:
    pass

class A:
    def method(self, x: "B") -> None:
        pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

# Create a wrapped method
# A().method is a bound method.
# functools.wraps(A().method) will copy __annotations__ from A.method
wrapped_method = wrapper(A().method)

print(f"Wrapped method: {wrapped_method}")
print(f"Wrapped method annotations: {getattr(wrapped_method, '__annotations__', 'No annotations')}")

try:
    sig = get_typed_signature(wrapped_method)
    print("Success!")
    print(sig)
except NameError as e:
    print(f"Caught expected NameError: {e}")
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")
    import traceback
    traceback.print_exc()

