# Python 3.10+ syntax
try:
    ann = list[int] | None
    print(f"list[int] | None: sequence={field_annotation_is_sequence(ann)}, scalar_sequence={field_annotation_is_scalar_sequence(ann)}")
except TypeError:
    print("Python version < 3.10")

# Traditional Optional
ann_opt = Optional[List[int]]
print(f"Optional[List[int]]: sequence={field_annotation_is_sequence(ann_opt)}, scalar_sequence={field_annotation_is_scalar_sequence(ann_opt)}")
